it('preserves non-negative integer list limits and rejects other limits', () => {
  const invalid = [-1, 1.5, '10', null, NaN, Infinity];
  expect(invalid.map(limit => validateMessage({type: 'list_sessions', limit}))).toEqual(
    invalid.map(() => ({valid: false, error: 'list_sessions limit must be a non-negative integer'}))
  );
  for (const limit of [0, 10, 200]) {
    expect(validateMessage({type: 'list_sessions', limit})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit},
    });
  }
});
EOF
